-- E01-T01a, hand-written from here.
-- No double booking (D-020, data-model.md): while an appointment is not cancelled or a no-show and
-- not booked anyway (overlap_ok), no other such appointment of the same provider may overlap it.
-- '[)': a range holds its start and not its end, so back-to-back visits do not overlap; the check
-- appointments_starts_at_check keeps every range non-empty. btree_gist (migration 0000) lets the
-- gist index compare the uuids with =. An update that changes the provider, the times, the status
-- or overlap_ok is checked again: restoring a cancelled appointment into an overlap is refused.
ALTER TABLE "appointments" ADD CONSTRAINT "appointments_no_double_booking"
  EXCLUDE USING gist (
    "clinic_id" WITH =,
    "provider_id" WITH =,
    tstzrange("starts_at", "ends_at", '[)') WITH &&
  )
  WHERE ("status" NOT IN ('cancelled', 'no_show') AND NOT "overlap_ok");
