-- clinics_for_user() (migration 0001, D-062) also returns the kind of the provider each membership
-- is linked to, or null (D-091): the sidebar and the action wrapper read it, before any clinic is
-- set. CREATE OR REPLACE cannot change what a function returns, so it is dropped and created again,
-- with both grants. It still takes one user id and returns only that user's active memberships; the
-- provider is joined on the membership's own clinic and its own provider_id, so a kind can only come
-- from that clinic's provider. SECURITY DEFINER with a fixed search_path, on the allow-list in
-- tests/integration/tenant-allow-list.ts.
DROP FUNCTION clinics_for_user(uuid);
--> statement-breakpoint
CREATE FUNCTION clinics_for_user(p_user_id uuid)
  RETURNS TABLE (
    membership_id uuid,
    clinic_id uuid,
    clinic_name text,
    role text,
    extra_permissions text[],
    provider_kind text
  )
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, public
  AS $$
    SELECT m.id, m.clinic_id, c.name, m.role, m.extra_permissions, p.kind
    FROM memberships m
    JOIN clinics c ON c.id = m.clinic_id
    LEFT JOIN providers p ON p.clinic_id = m.clinic_id AND p.id = m.provider_id
    WHERE m.user_id = p_user_id AND m.status = 'active'
    ORDER BY c.name, m.clinic_id
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION clinics_for_user(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION clinics_for_user(uuid) TO chairside_app;